import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    found = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            found = True
            proc.terminate()
    if found:
        time.sleep(0.5)
        subprocess.Popen(process_name, shell=True)
        return f"Process found. Restarting {process_name}."
    else:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    result = {}
    for ip in network.hosts():
        try:
            subprocess.check_output(['ping', '-c', '1', '-W', '1', str(ip)], stderr=subprocess.DEVNULL)
            result[str(ip)] = True
        except subprocess.CalledProcessError:
            result[str(ip)] = False
    return result

def task_func(directory, backup_dir='/path/to/backup'):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory not found: {directory}")
    pattern = os.path.join(directory, '*.cf.log')
    files = glob.glob(pattern)
    if not files:
        return 'No logs found to backup'
    backup_path = os.path.join(backup_dir, 'logs_backup.tar.gz')
    file_names = [os.path.basename(f) for f in files]
    subprocess.run(['tar', '-czf', backup_path] + file_names, cwd=directory)
    for f in files:
        os.remove(f)
    return backup_path

