import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}
    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    if not files:
        return {'success': True, 'message': 'No files to process.', 'failed_files': []}
    failed_files = []
    for fname in files:
        src_path = os.path.join(src_folder, fname)
        try:
            subprocess.run(['gzip', src_path], check=True, capture_output=True)
        except subprocess.CalledProcessError:
            failed_files.append(fname)
            continue
        gz_path = src_path + '.gz'
        try:
            shutil.move(gz_path, os.path.join(dst_folder, fname + '.gz'))
        except Exception:
            failed_files.append(fname)
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully.', 'failed_files': []}
    else:
        return {'success': False, 'message': f'Failed to process {len(failed_files)} file(s).', 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(['bash', script_path])
    p = psutil.Process(proc.pid)
    start_time = time.time()
    cpu_times_start = p.cpu_times()
    rss_initial = p.memory_info().rss
    total_rss_increment = 0
    last_rss = rss_initial
    while True:
        time.sleep(0.1)
        if not p.is_running():
            break
        if time.time() - start_time >= timeout:
            p.terminate()
            p.wait()
            break
        try:
            current_rss = p.memory_info().rss
            if current_rss > last_rss:
                total_rss_increment += current_rss - last_rss
                last_rss = current_rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    try:
        cpu_times_end = p.cpu_times()
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        cpu_times_end = p.cpu_times()
    wall_time = time.time() - start_time
    total_cpu_time = (cpu_times_end.user + cpu_times_end.system) - (cpu_times_start.user + cpu_times_start.system)
    if wall_time > 0:
        cpu_usage = (total_cpu_time / wall_time) * 100
    else:
        cpu_usage = 0.0
    return {'CPU Usage': cpu_usage, 'Memory Usage': total_rss_increment}
